package net.civeira.phylax.feature.identity.userprofile.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.userprofile.domain.UserProfile;
import net.civeira.phylax.feature.identity.userprofile.domain.valueobject.NicknameVO;

class NicknameValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of nickname of user profile")
  void test_nickname_value_holder_assign_plain_value() {
    Object holder = new Object();
    NicknameValueHolder<Object> value = new NicknameValueHolder<>(holder);
    Assertions.assertSame(holder, value.nickname("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getNicknameValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getNickname().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.nicknameNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getNicknameValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getNickname().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of nickname of user profile")
  void test_nickname_value_holder_assign_value_object() {
    Object holder = new Object();
    NicknameValueHolder<Object> value = new NicknameValueHolder<>(holder);
    NicknameVO vo = NicknameVO.from("one");
    Assertions.assertFalse(value.getNicknameValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.nickname(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getNicknameValue().orElseThrow());
    Assertions.assertSame(holder, value.nickname(Optional.empty()));
    Assertions.assertFalse(value.getNicknameValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.nickname(Optional.of(vo)));
    Assertions.assertSame(vo, value.getNicknameValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of nickname of user profile against the original")
  void test_nickname_value_holder_read() {
    Object holder = new Object();
    NicknameValueHolder<Object> value = new NicknameValueHolder<>(holder);
    NicknameVO vo = NicknameVO.from("one");
    NicknameVO other = NicknameVO.from("one");
    UserProfile original = Mockito.mock(UserProfile.class);
    Mockito.when(original.getNicknameValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readNickname(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readNickname(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.nickname(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readNickname(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readNickname(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of nickname of user profile")
  void test_nickname_value_holder_unset() {
    Object holder = new Object();
    NicknameValueHolder<Object> value = new NicknameValueHolder<>(holder);
    NicknameVO vo = NicknameVO.from("one");
    value.nickname(vo);
    Assertions.assertSame(holder, value.unsetNicknameIfMatches("nickname_other"));
    Assertions.assertTrue(value.getNicknameValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetNicknameIfMatches("nickname"));
    Assertions.assertFalse(value.getNicknameValue().isPresent(),
        "The field name must clear the value");
    value.nickname(vo);
    Assertions.assertSame(holder, value.unsetNickname());
    Assertions.assertFalse(value.getNicknameValue().isPresent(), "Unset must clear the value");
  }
}
